begin;
select pg_temp.assert_true(helm_channex_delivery_cycle_claim(gen_random_uuid())->>'status'='disabled','cycle dormant');
select pg_temp.assert_true(helm_channex_delivery_operations()->>'publishingEnabled'='false','status reports disabled');
select pg_temp.assert_true(not has_function_privilege('anon','helm_channex_delivery_operations()','EXECUTE'),'public status denied');
select pg_temp.assert_true(not has_function_privilege('authenticated','helm_channex_delivery_cycle_claim(uuid)','EXECUTE'),'staff cannot run worker');
select pg_temp.assert_true(has_function_privilege('service_role','helm_channex_delivery_operations()','EXECUTE'),'service status permitted');
select channex_synthetic_inventory_setup();
select channex_synthetic_inventory_save(channex_synthetic_inventory_request());
update helm_airbnb_bookings.delivery_scope set enabled=true;
create temporary table cycle_selected as select helm_channex_delivery_cycle_claim(gen_random_uuid()) selection;
select pg_temp.assert_true((select selection->>'status' from cycle_selected)='selected','cycle selects persisted lease');
select pg_temp.assert_true((select helm_channex_delivery_cycle_claim(gen_random_uuid())=selection from cycle_selected),'restart resumes saved token');
select pg_temp.assert_true((select count(*) from helm_airbnb_bookings.delivery_attempts)=1,'restart creates no second attempt');
select pg_temp.assert_true(helm_channex_delivery_operations()->'active'->>'state'='leased','status shows pending lease');
select helm_channex_delivery_begin(token,request_digest) from helm_airbnb_bookings.delivery_attempts;
select pg_temp.assert_true(helm_channex_delivery_cycle_claim(gen_random_uuid())->>'status'='blocked','no immediate replacement after send checkpoint');
select helm_channex_delivery_record(token,request_digest,'{"kind":"uncertain"}') from helm_airbnb_bookings.delivery_attempts;
update helm_airbnb_bookings.delivery_attempts set expires_at=0,started_at=clock_timestamp()-interval '2 minutes';
update helm_airbnb_bookings.delivery_scope set next_attempt_at='-infinity';
select helm_create_booking('65_calderwood','direct','manual','block','2039-01-01','2039-01-03','{"hold_kind":"owner"}');
select pg_temp.assert_true(helm_channex_delivery_cycle_claim(gen_random_uuid())->>'status'='stale','worker cannot recover stale canonical source');
select channex_synthetic_inventory_save(channex_synthetic_inventory_request());
create temporary table cycle_recovered as select helm_channex_delivery_cycle_claim(gen_random_uuid()) selection;
select pg_temp.assert_true((select selection->>'status' from cycle_recovered)='selected','cycle selects recovery');
select pg_temp.assert_true((select selection from cycle_recovered)<>(select selection from cycle_selected),'recovery uses new token');
select pg_temp.assert_true((select helm_channex_delivery_cycle_claim(gen_random_uuid())=selection from cycle_recovered),'lost recovery selection resumes replacement');
select pg_temp.assert_true(helm_channex_delivery_operations()->'counts'->>'historicalUnknown'='1','history remains unknown');
select pg_temp.assert_true(helm_channex_delivery_operations()->'active'->>'state'='leased','history does not obscure current prepared state');
select pg_temp.assert_true(helm_channex_delivery_operations()->>'consecutiveRecoveries'='1','status includes recovery budget');
select pg_temp.assert_true(helm_channex_delivery_operations()::text !~ 'requestBody|request_body|taskId|task_id|token|phone|email','status excludes payloads and identities');
select pg_temp.assert_true(jsonb_array_length(helm_channex_delivery_operations()->'recent')=2,'bounded history includes both attempts');
select helm_channex_delivery_begin(token,request_digest) from helm_airbnb_bookings.delivery_attempts where superseded_by is null;
select helm_channex_delivery_record(token,request_digest,'{"kind":"accepted","taskId":"ffffffff-ffff-4fff-8fff-ffffffffffff"}') from helm_airbnb_bookings.delivery_attempts where superseded_by is null;
select pg_temp.assert_true(helm_channex_delivery_cycle_claim(gen_random_uuid())->>'status'='already-accepted','cycle deduplicates exact acceptance');
select pg_temp.assert_true(helm_channex_delivery_operations()->'active'='null'::jsonb,'no active lane after acceptance');
select pg_temp.assert_true(helm_channex_delivery_operations()->'counts'->>'accepted'='1','acceptance count separate from unknown history');
rollback;
select 'PASS: cycle restart, lost selection, latest-state recovery and private bounded operations snapshot' as result;
